host=new();host.mcpClients["cloudflare"].Tools.Add(new("status","Read deployment status",schema,true));host.Result=_=>"pending";LocalApi.Next=(_,_)=>Call("status");reply=await host.Run("Проверь статус MCP");Check(reply.TaskPending&&host.Executed.Count<=5,"unchanged read-only polling remains bounded by progress guard");
